; Sprites and actor speeds of a lawn
; $9021-$9065

; Second part of the actor setup at $8ff6. It turns on sprites 0-3 and sets the speeds of the lawn from the lawn number $21.
        lda #$0f
        sta SPENA                       ; $d015: sprites 0,1,2,3
        lda #$1b                        ; Multicolour for sprites 0, 1, 3 and 4.
        sta SPMC                        ; $d01c: sprites 0,1,3,4
        lda #$02                        ; $57 = 2: two actors move. $5c: the countdown of the DOG LOYALTY decrease.
        sta actor_count
        sta loyalty_timer
        ldx lawn_number                 ; (Lawn number - 1) AND $f0 is not 0 after lawn 16.
        dex
        txa
        and #$f0
        beq speed_by_lawn_number
        lda #$02                        ; Maximum speed after lawn 16: $60 = 2 and the actor period 4.
        sta loyalty_rate
        lda #$04
        jmp actor_period_set
; Lawns 1-16. LDX does not change A, so A is 0 here and $94bd returns 0. Thus the loyalty period $60 is always 6.
speed_by_lawn_number
        ldx lawn_number
        jsr divide_by_4
        sta work_ptr
        lda #$06
        sec
        sbc work_ptr
        sta loyalty_rate
        lda lawn_number                 ; $50 = 12 - (lawn AND $0f) / 2. Lawn 16 gives 12, as lawn 1 does.
        and #$0f
        clc
        ror
        sta work_ptr
        lda #$0c
        sec
        sbc work_ptr
actor_period_set
        sta actor_speed                 ; $50: the period of the actor moves. $58: its countdown.
        sta actor_timer
actor_setup_return
        rts                             ; The byte before actor_colours.
; Sprite colour of actors 1-4 (sprites 2-5): black dog, yellow neighbour, dark grey gardener, light red actor 4.
actor_colours
        !byte $00,$07,$0b,$0a
